import React, { useState } from "react";
import axios from "axios";

const Upload = () => {
  const [image, setImage] = useState(null);
  const [preview, setPreview] = useState(null);
  const [resultImage, setResultImage] = useState(null);
  const [loading, setLoading] = useState(false);

  // Handle file select
  const handleImageChange = (e) => {
  const selectedFile = e.target.files[0];

  // 🛑 The Fix: Only proceed if a file was actually selected
  if (selectedFile) {
    setFile(selectedFile);
    setImagePreview(URL.createObjectURL(selectedFile));
  } else {
    // If no file (user clicked cancel), do nothing or reset
    console.log("No file selected");
  }
};

  // Drag & Drop
  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    handleImageChange(file);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  // Detect (Send to Flask YOLO backend)
  const handleDetect = async () => {
    if (!image) {
      alert("Please upload an image first!");
      return;
    }

    const formData = new FormData();
    // FIX 1: Must match Flask's request.files["image"]
    formData.append("image", image);

    try {
      setLoading(true);

      const response = await axios.post(
        "http://127.0.0.1:5000/detect",
        formData,
        {
          headers: { "Content-Type": "multipart/form-data" },
        }
      );

      // FIX 2: Must match Flask's returned JSON key "result_image"
      // Adding a timestamp forces the browser to load the newest image
setResultImage(`${response.data.result_image}?t=${new Date().getTime()}`);
      setLoading(false);
    } catch (error) {
      console.error(error);
      alert("Detection failed!");
      setLoading(false);
    }
  };

  // Clear
  const handleClear = () => {
    setImage(null);
    setPreview(null);
    setResultImage(null);
  };

  return (
    <div className="upload-container">
      <h2>📤 Upload Image</h2>
      <p>
        Upload your underwater image for object detection using YOLOv8 model.
      </p>

      {/* Drag & Drop Area */}
      <div
        className="drop-area"
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onClick={() => document.getElementById("fileInput").click()}
      >
        {preview ? (
          <img
            src={preview}
            alt="Preview"
            style={{ width: "300px", borderRadius: "10px" }}
          />
        ) : (
          <p>Drag & Drop or Click to Upload</p>
        )}
      </div>

      <input
        type="file"
        id="fileInput"
        hidden
        accept="image/*"
        onChange={(e) => handleImageChange(e.target.files[0])}
      />

      {/* Buttons */}
      <div className="button-group">
        <button className="glass-btn detect-btn" onClick={handleDetect}>
          {loading ? "Detecting..." : "🔍 Detect Objects"}
        </button>

        <button className="glass-btn clear-btn" onClick={handleClear}>
          🗑 Clear Images
        </button>
      </div>

      {/* Result */}
      {resultImage && (
        <div style={{ marginTop: "30px" }}>
          <h3>✅ Detection Result</h3>
          <img
            src={resultImage}
            alt="Result"
            style={{ width: "300px", borderRadius: "10px" }}
          />
        </div>
      )}
    </div>
  );
};

export default Upload;
